import json
import pandas as pd
import numpy as np
import pyarrow as pa
import pyarrow.parquet as pq
from datetime import datetime

source_a_path = '/data/source_a/users.json'
source_b_path = '/data/source_b/users.csv'
source_c_path = '/data/source_c/users.parquet'

# Read sources
with open(source_a_path, 'r') as f:
    data_a = json.load(f)

df_a = pd.DataFrame(data_a)

df_b = pd.read_csv(source_b_path)

df_c = pq.read_table(source_c_path).to_pandas()

# Normalize helpers
ID_FIELDS = ['user_id', 'id', 'userId']
EMAIL_FIELDS = ['email', 'email_address']
NAME_FIELDS = ['full_name', 'name', 'userName']
DATE_FIELDS = ['registration_date', 'created_at', 'joined']
STATUS_FIELDS = ['status', 'is_active', 'active']


def pick_first(row, fields):
    for f in fields:
        if f in row and pd.notna(row[f]):
            return row[f]
    return None


def normalize_status(val):
    if pd.isna(val):
        return None
    if isinstance(val, (bool, np.bool_)):
        return 'active' if val else 'inactive'
    if isinstance(val, (int, np.integer)):
        return 'active' if val else 'inactive'
    if isinstance(val, str):
        v = val.strip().lower()
        if v in ['true', 'yes', '1', 'active']:
            return 'active'
        if v in ['false', 'no', '0', 'inactive']:
            return 'inactive'
        return val.strip()
    return str(val)


def normalize_date(val):
    if pd.isna(val):
        return None
    if isinstance(val, str):
        val = val.strip()
        if not val:
            return None
    try:
        dt = pd.to_datetime(val)
        if pd.isna(dt):
            return None
        return dt.strftime('%Y-%m-%d')
    except Exception:
        return None


def normalize_df(df):
    records = []
    for _, row in df.iterrows():
        row_dict = row.to_dict()
        user_id = pick_first(row_dict, ID_FIELDS)
        name = pick_first(row_dict, NAME_FIELDS)
        email = pick_first(row_dict, EMAIL_FIELDS)
        created = pick_first(row_dict, DATE_FIELDS)
        status_raw = pick_first(row_dict, STATUS_FIELDS)
        status = normalize_status(status_raw)
        created_date = normalize_date(created)
        if pd.isna(user_id):
            continue
        records.append({
            'user_id': int(user_id),
            'name': None if pd.isna(name) else name,
            'email': None if pd.isna(email) else email,
            'created_date': created_date,
            'status': status,
        })
    return records

records_a = normalize_df(df_a)
records_b = normalize_df(df_b)
records_c = normalize_df(df_c)

# Build per-source dicts
source_maps = {
    'source_a': {rec['user_id']: rec for rec in records_a},
    'source_b': {rec['user_id']: rec for rec in records_b},
    'source_c': {rec['user_id']: rec for rec in records_c},
}

priority = ['source_a', 'source_b', 'source_c']
fields = ['name', 'email', 'created_date', 'status']

all_user_ids = set()
for sm in source_maps.values():
    all_user_ids.update(sm.keys())

conflicts = []

for user_id in sorted(all_user_ids):
    # collect values per field per source
    for field in fields:
        values = {}
        distinct_vals = []
        for src in priority:
            rec = source_maps[src].get(user_id)
            val = rec.get(field) if rec else None
            if val is not None and isinstance(val, float) and np.isnan(val):
                val = None
            values[src] = val
            if val is not None:
                distinct_vals.append(val)
        # Check for conflict: more than one distinct non-null value
        if len(distinct_vals) > 1 and len(set(distinct_vals)) > 1:
            # selected value based on priority
            selected = None
            for src in priority:
                if values[src] is not None:
                    selected = values[src]
                    break
            conflicts.append({
                'user_id': user_id,
                'field': field,
                'values': values,
                'selected': selected,
            })

# Merge records
merged_records = []
for user_id in sorted(all_user_ids):
    merged = {'user_id': int(user_id)}
    for field in fields:
        selected = None
        for src in priority:
            rec = source_maps[src].get(user_id)
            if rec:
                val = rec.get(field)
                if val is not None:
                    selected = val
                    break
        merged[field] = selected
    merged_records.append(merged)

merged_df = pd.DataFrame(merged_records, columns=['user_id', 'name', 'email', 'created_date', 'status'])

# Ensure types
merged_df['user_id'] = merged_df['user_id'].astype('int64')

# Write parquet
output_parquet = '/app/merged_users.parquet'
pq.write_table(pa.Table.from_pandas(merged_df), output_parquet)

# Write conflicts
conflict_report = {
    'total_conflicts': len(conflicts),
    'conflicts': conflicts,
}
with open('/app/conflicts.json', 'w') as f:
    json.dump(conflict_report, f, indent=2)

print('Merged users:', merged_df)
print('Conflicts:', conflict_report['total_conflicts'])
